def format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Convert the SQL query to use the out-style parameters instead of the in-style parameters
    formatted_sql = sql
    formatted_params = {}
    for i, param in enumerate(params):
        param_key = f"p{i}" if isinstance(param, str) else i
