def validate_fixity(self, fixity, manifest_files):
    if not fixity:
        raise MissingBlockError("Fixity block missing from inventory")

    files_in_manifest = set(manifest_files.keys())
    files_referenced_in_inventory = set()
    for file in fixity:
        content = file.get("content", None)
        if not content:
            raise MissingFieldError("Content field missing from fixity block")
        files_referenced_in_inventory.add(content)

    missing_files = files_referenced_in_inventory - files_in_manifest
    if missing_files:
        raise InventoryError("The following files are missing from the manifest: %s" % str(missing_files))

    extra_files = files_in_manifest - files_referenced_in_inventory
    if extra_files:
        raise InventoryError("The following files are not referenced in the fixity block: %s" % str(extra_files))

    for file in fixity:
        content = file.get("content", None)
        if not content:
            raise MissingFieldError("Content field missing from fixity block")
        digest = file.get("digest", None)
        if not digest:
            raise MissingFieldError("Digest field missing from fixity block")
