def deep_merge_nodes(nodes):
    nodes = [*nodes]
    if len(nodes) == 0:
        return nodes

    i = 0
    while i < len(nodes):
        base_key, base_value = nodes[i]
        for j in range(i + 1, len(nodes)):
            cur_key, cur_value = nodes[j]
            if base_key.value == cur_key.value:
                nodes[i] = (base_key, _deep_merge(base_value, cur_value))
                nodes.pop(j)
                break
        i += 1

    return nodes

def _deep_merge(base, other):
    if type(base) != type(other):
        return other
    if type(base) is dict:
        for k, v in other.items():
            if k in base:
                base[k] = _deep_merge(base[k], v)
        return base
    elif type(base) is list:
        result = []
        for e in other:
            if e not in base:
                result.append(e)
            else:
                index = base.index(e)
                result.insert(index, _deep_merge(base[index], e))
                base.pop(index)
        return result + base
    else:
        return other

