def find_tags(text, replacer=None):
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    char_iter = iter(text)
    code_block = False
    pattern = r"<[^\>]*>"

    def handle_tag(tag):
        tags.add(tag)
        if replacer:
            return replacer(tag)
        return tag

    for char in char_iter:
        if char == "<" and next(char_iter) == "<":
            code_block = True
            continue
        if char == ">" and next(char_iter) == ">":
            code_block = False
            continue
        if code_block:
            continue
        tag = re.fullmatch(pattern, char, re.IGNORECASE)
        if tag:
            handle_tag(tag.group())

    text = "".join(char_iter)
    if replacer:
        text = re.sub(pattern, replacer, text, re.IGNORECASE)

    return tags, text

